/// Frames the speedometer averages over.
const SMOOTHING: i32 = 30;

scene.set_counter("speed", (speed * 100.0).round() as i32);
// The speedometer shows the average speed over the last SMOOTHING frames.
let frame = scene.add_to_counter("frame", 1);
scene.set_counter(&format!("speed_at_{frame}"), (speed * 100.0).round() as i32);
let first = (frame - SMOOTHING + 1).max(1);
let sum: i32 = (first..=frame)
    .map(|f| scene.counter_value(&format!("speed_at_{f}")))
    .sum();
scene.set_counter("shown_speed", sum / (frame - first + 1));
